package java.text;
import java.util.Calendar;import java.util.Date;import java.util.Locale;import java.util.TimeZone;
public class SimpleDateFormat extends DateFormat {
 private String pattern;private static final String[] MONTHS={"January","February","March","April","May","June","July","August","September","October","November","December"},DAYS={"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"};
 public SimpleDateFormat(){this("M/d/yy, h:mm a",Locale.US);}public SimpleDateFormat(String p){this(p,Locale.getDefault());}public SimpleDateFormat(String p,Locale l){pattern=p;}public void applyPattern(String p){pattern=p;}public String toPattern(){return pattern;}
 private static void number(StringBuffer b,int v,int n){String x=Integer.toString(v);for(int i=x.length();i<n;i++)b.append('0');b.append(x);}
 public StringBuffer format(Date d,StringBuffer b,FieldPosition p){Calendar c=Calendar.getInstance(zone);c.setTime(d);boolean quote=false;for(int i=0;i<pattern.length();){char ch=pattern.charAt(i);if(ch=='\''){if(i+1<pattern.length()&&pattern.charAt(i+1)=='\''){b.append('\'');i+=2;}else{quote=!quote;i++;}continue;}if(quote){b.append(ch);i++;continue;}int j=i+1;while(j<pattern.length()&&pattern.charAt(j)==ch)j++;int n=j-i;switch(ch){case 'y':int y=c.get(Calendar.YEAR);number(b,n==2?y%100:y,n==2?2:n);break;case 'M':int m=c.get(Calendar.MONTH);if(n>=4)b.append(MONTHS[m]);else if(n==3)b.append(MONTHS[m].substring(0,3));else number(b,m+1,n);break;case 'd':number(b,c.get(Calendar.DATE),n);break;case 'H':number(b,c.get(Calendar.HOUR_OF_DAY),n);break;case 'h':int h=c.get(Calendar.HOUR);number(b,h==0?12:h,n);break;case 'm':number(b,c.get(Calendar.MINUTE),n);break;case 's':number(b,c.get(Calendar.SECOND),n);break;case 'S':number(b,c.get(Calendar.MILLISECOND),n);break;case 'a':b.append(c.get(Calendar.AM_PM)==0?"AM":"PM");break;case 'E':String day=DAYS[c.get(Calendar.DAY_OF_WEEK)-1];b.append(n>=4?day:day.substring(0,3));break;case 'z':b.append(zone.getID());break;case 'Z':int off=zone.getRawOffset()/60000;b.append(off<0?'-':'+');off=Math.abs(off);number(b,off/60,2);number(b,off%60,2);break;default:for(int k=0;k<n;k++)b.append(ch);}i=j;}return b;}
 public Date parse(String text,ParsePosition pos){int start=pos.getIndex(),t=start,year=1970,month=0,day=1,hour=0,min=0,sec=0,ms=0,ampm=0;boolean twelve=false,quote=false;TimeZone z=zone;for(int i=0;i<pattern.length();){char ch=pattern.charAt(i);if(ch=='\''){if(i+1<pattern.length()&&pattern.charAt(i+1)=='\''){if(t>=text.length()||text.charAt(t++)!='\'')return fail(pos,t);i+=2;}else{quote=!quote;i++;}continue;}int j=i+1;while(j<pattern.length()&&pattern.charAt(j)==ch)j++;int n=j-i;if(quote){for(int k=0;k<n;k++)if(t>=text.length()||text.charAt(t++)!=ch)return fail(pos,t);i=j;continue;}if(ch=='M'&&n>=3||ch=='E'){String[] arr=ch=='M'?MONTHS:DAYS;int found=-1,used=0;for(int k=0;k<arr.length;k++){String x=arr[k];if(text.regionMatches(true,t,x,0,x.length())){found=k;used=x.length();break;}x=x.substring(0,3);if(text.regionMatches(true,t,x,0,3)){found=k;used=3;}}if(found<0)return fail(pos,t);if(ch=='M')month=found;t+=used;}else if(ch=='a'){if(text.regionMatches(true,t,"AM",0,2))ampm=0;else if(text.regionMatches(true,t,"PM",0,2))ampm=1;else return fail(pos,t);t+=2;}else if(ch=='z'){if(text.startsWith("UTC",t)||text.startsWith("GMT",t)){int end=t+3;if(text.startsWith("GMT",t)&&end<text.length()&&(text.charAt(end)=='+'||text.charAt(end)=='-')){int k=end+1;while(k<text.length()&&((text.charAt(k)>='0'&&text.charAt(k)<='9')||text.charAt(k)==':'))k++;end=k;}z=TimeZone.getTimeZone(text.substring(t,end));t=end;}else return fail(pos,t);}else if(ch=='Z'){if(t+5>text.length()||(text.charAt(t)!='+'&&text.charAt(t)!='-'))return fail(pos,t);z=TimeZone.getTimeZone("GMT"+text.substring(t,t+3)+":"+text.substring(t+3,t+5));t+=5;}else if("yMdHhmsS".indexOf(ch)>=0){int v=0,count=0;boolean adjacent=j<pattern.length()&&"yMdHhmsS".indexOf(pattern.charAt(j))>=0;while(t<text.length()&&text.charAt(t)>='0'&&text.charAt(t)<='9'&&(!adjacent||count<n)){v=v*10+text.charAt(t++)-'0';count++;}if(count==0)return fail(pos,t);switch(ch){case 'y':year=v;if(n==2&&count==2)year=v>=46?1900+v:2000+v;break;case 'M':month=v-1;break;case 'd':day=v;break;case 'H':hour=v;break;case 'h':hour=v;twelve=true;break;case 'm':min=v;break;case 's':sec=v;break;case 'S':ms=v;break;}}else{for(int k=0;k<n;k++)if(t>=text.length()||text.charAt(t++)!=ch)return fail(pos,t);}i=j;}if(twelve)hour=hour%12+ampm*12;Calendar c=Calendar.getInstance(z);c.set(year,month,day,hour,min,sec);c.set(Calendar.MILLISECOND,ms);pos.setIndex(t);return c.getTime();}
 private Date fail(ParsePosition p,int i){p.setErrorIndex(i);return null;}
}
